class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> dictionary = new HashSet<>(wordList);
        List<List<String>> result = new ArrayList<>();
        if (!dictionary.contains(endWord)) {
            return result;
        }

        Map<String, Integer> distance = new HashMap<>();
        Map<String, List<String>> children = new HashMap<>();
        Queue<String> queue = new ArrayDeque<>();
        queue.offer(beginWord);
        distance.put(beginWord, 0);
        boolean found = false;

        while (!queue.isEmpty() && !found) {
            int size = queue.size();
            for (int levelIndex = 0; levelIndex < size; levelIndex++) {
                String word = queue.poll();
                int currentDistance = distance.get(word);
                char[] chars = word.toCharArray();
                for (int i = 0; i < chars.length; i++) {
                    char original = chars[i];
                    for (char letter = 'a'; letter <= 'z'; letter++) {
                        if (letter == original) {
                            continue;
                        }
                        chars[i] = letter;
                        String next = new String(chars);
                        if (!dictionary.contains(next)) {
                            continue;
                        }
                        if (!distance.containsKey(next)) {
                            distance.put(next, currentDistance + 1);
                            queue.offer(next);
                            if (next.equals(endWord)) {
                                found = true;
                            }
                        }
                        if (distance.get(next) == currentDistance + 1) {
                            children.computeIfAbsent(word, key -> new ArrayList<>()).add(next);
                        }
                    }
                    chars[i] = original;
                }
            }
        }

        if (found) {
            List<String> path = new ArrayList<>();
            path.add(beginWord);
            dfs(children, beginWord, endWord, path, result);
        }
        return result;
    }

    private void dfs(Map<String, List<String>> children, String word, String endWord,
                     List<String> path, List<List<String>> result) {
        if (word.equals(endWord)) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (String next : children.getOrDefault(word, Collections.emptyList())) {
            path.add(next);
            dfs(children, next, endWord, path, result);
            path.remove(path.size() - 1);
        }
    }
}

