class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> dictionary = new HashSet<>(wordList);
        List<List<String>> result = new ArrayList<>();
        if (!dictionary.contains(endWord)) {
            return result;
        }

        List<String> words = new ArrayList<>(wordList);
        if (!dictionary.contains(beginWord)) {
            words.add(beginWord);
        }
        Map<String, List<String>> patternMap = new HashMap<>();
        for (String word : words) {
            addPatterns(word, patternMap);
        }

        Map<String, List<String>> parents = new HashMap<>();
        Queue<String> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        queue.offer(beginWord);
        visited.add(beginWord);
        boolean found = false;

        while (!queue.isEmpty() && !found) {
            int size = queue.size();
            Set<String> levelVisited = new HashSet<>();
            for (int levelIndex = 0; levelIndex < size; levelIndex++) {
                String word = queue.poll();
                for (int i = 0; i < word.length(); i++) {
                    String pattern = word.substring(0, i) + "*" + word.substring(i + 1);
                    for (String next : patternMap.getOrDefault(pattern, Collections.emptyList())) {
                        if (next.equals(word) || visited.contains(next)) {
                            continue;
                        }
                        if (levelVisited.add(next)) {
                            queue.offer(next);
                        }
                        parents.computeIfAbsent(next, key -> new ArrayList<>()).add(word);
                        if (next.equals(endWord)) {
                            found = true;
                        }
                    }
                }
            }
            visited.addAll(levelVisited);
        }

        if (found) {
            LinkedList<String> path = new LinkedList<>();
            path.add(endWord);
            buildPaths(parents, beginWord, endWord, path, result);
        }
        return result;
    }

    private void addPatterns(String word, Map<String, List<String>> patternMap) {
        for (int i = 0; i < word.length(); i++) {
            String pattern = word.substring(0, i) + "*" + word.substring(i + 1);
            patternMap.computeIfAbsent(pattern, key -> new ArrayList<>()).add(word);
        }
    }

    private void buildPaths(Map<String, List<String>> parents, String beginWord, String word,
                            LinkedList<String> path, List<List<String>> result) {
        if (word.equals(beginWord)) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (String parent : parents.getOrDefault(word, Collections.emptyList())) {
            path.addFirst(parent);
            buildPaths(parents, beginWord, parent, path, result);
            path.removeFirst();
        }
    }
}

