class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> dictionary = new HashSet<>(wordList);
        List<List<String>> result = new ArrayList<>();
        if (!dictionary.contains(endWord)) {
            return result;
        }

        Map<String, LinkedHashSet<String>> children = new HashMap<>();
        LinkedHashSet<String> front = new LinkedHashSet<>();
        LinkedHashSet<String> back = new LinkedHashSet<>();
        front.add(beginWord);
        back.add(endWord);
        boolean reversed = false;
        boolean found = false;

        while (!front.isEmpty() && !back.isEmpty() && !found) {
            if (front.size() > back.size()) {
                LinkedHashSet<String> temp = front;
                front = back;
                back = temp;
                reversed = !reversed;
            }

            dictionary.removeAll(front);
            LinkedHashSet<String> nextFront = new LinkedHashSet<>();
            for (String word : front) {
                char[] chars = word.toCharArray();
                for (int i = 0; i < chars.length; i++) {
                    char original = chars[i];
                    for (char letter = 'a'; letter <= 'z'; letter++) {
                        if (letter == original) {
                            continue;
                        }
                        chars[i] = letter;
                        String next = new String(chars);
                        if (!back.contains(next) && !dictionary.contains(next)) {
                            continue;
                        }

                        String parent = reversed ? next : word;
                        String child = reversed ? word : next;
                        if (back.contains(next)) {
                            found = true;
                            children.computeIfAbsent(parent, key -> new LinkedHashSet<>()).add(child);
                        } else if (!found) {
                            nextFront.add(next);
                            children.computeIfAbsent(parent, key -> new LinkedHashSet<>()).add(child);
                        }
                    }
                    chars[i] = original;
                }
            }
            front = nextFront;
        }

        if (found) {
            List<String> path = new ArrayList<>();
            path.add(beginWord);
            buildPaths(beginWord, endWord, children, path, result);
        }
        return result;
    }

    private void buildPaths(String word, String endWord, Map<String, LinkedHashSet<String>> children,
                            List<String> path, List<List<String>> result) {
        if (word.equals(endWord)) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (String next : children.getOrDefault(word, new LinkedHashSet<>())) {
            path.add(next);
            buildPaths(next, endWord, children, path, result);
            path.remove(path.size() - 1);
        }
    }
}
